/* Lot 104: view-timeline-inset, view-timeline, view() insets and length edges (generated by scripts/lot104_gen.py; expectations from scripts/lot104_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[512];
static wf_csstl_t g_t[8];
static int g_tn;
static wf_cssanim_t g_a[8];
static int g_n;

static const char *tl_items(int n) {
    int k, m = snprintf(g_o, sizeof(g_o), "%d:", n);
    for (k = 0; k < n && m < (int)sizeof(g_o); k++)
        m += snprintf(g_o + m, sizeof(g_o) - (size_t)m, " %s/%d/%d %d/%d %d", g_t[k].name[0] ? g_t[k].name : "-",
                      g_t[k].axis, g_t[k].ik[0], g_t[k].iv[0], g_t[k].ik[1], g_t[k].iv[1]);
    return g_o;
}

static const char *tp(int which, const char *v, int max) {
    int n, k;
    memset(g_t, 0x5a, sizeof(g_t));
    n = wf_csstl_parse(which, v, g_t, max);
    for (k = n < 0 ? 8 : n; k < 8; k++) if (g_t[k].axis != 0x5a || g_t[k].ik[0] != 0x5a) return "WRITTEN";
    g_tn = n;
    if (n < 0) return "-1";
    return tl_items(n);
}

static const char *ttx(int cap) {
    static char t[256], r[300];
    int n;
    memset(t, 'q', sizeof(t));
    n = wf_csstl_text(g_t, g_tn, 2, t, cap);
    if (n != (int)strlen(t)) return "BAD LENGTH";
    snprintf(r, sizeof(r), "%d %s", n, t);
    return r;
}

static const char *tc(const char *names, const char *axes, const char *insets) {
    int n;
    memset(g_t, 0x5a, sizeof(g_t));
    n = wf_csstl_coord_ex(names, axes, insets, g_t, 8);
    return tl_items(n);
}

static int tl(const char *v) {
    memset(g_a, 0x5a, sizeof(g_a));
    return wf_cssanim_long(WF_CSSANIM_L_TIMELINE, v, g_a, WF_CSSANIM_MAX);
}

static const char *tlf(int j) {
    const wf_cssanim_t *a = &g_a[j];
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d %d %d", a->timeline, a->tlsrc, a->tlaxis, a->vik[0], a->viv[0],
             a->vik[1], a->viv[1]);
    return g_o;
}

static int rl(int end, const char *v) {
    memset(g_a, 0x5a, sizeof(g_a));
    return wf_cssanim_long(end ? WF_CSSANIM_L_RANGE_END : WF_CSSANIM_L_RANGE_START, v, g_a, WF_CSSANIM_MAX);
}

static const char *rf(int j, int end) {
    snprintf(g_o, sizeof(g_o), "%d %d %d", end ? g_a[j].re : g_a[j].rs, end ? g_a[j].rep : g_a[j].rsp,
             end ? g_a[j].rel : g_a[j].rsl);
    return g_o;
}

static int rs(const char *v) {
    memset(g_a, 0x5a, sizeof(g_a));
    g_n = wf_cssanim_range(v, g_a, WF_CSSANIM_MAX);
    return g_n;
}

static const char *rboth(int j) {
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d %d", g_a[j].rs, g_a[j].rsp, g_a[j].rsl, g_a[j].re, g_a[j].rep,
             g_a[j].rel);
    return g_o;
}

static const char *rtx(int end, int cap) {
    static char t[256], r[300];
    int n;
    memset(t, 'q', sizeof(t));
    n = wf_cssanim_range_text(g_a, g_n, end, t, cap);
    if (n != (int)strlen(t)) return "BAD LENGTH";
    snprintf(r, sizeof(r), "%d %s", n, t);
    return r;
}

static void test_l104_parse_0(void) {
    TEST_ASSERT_EQUAL_STRING("2: -/0/2 333333/1 999990000 -/0/1 944882/2 -50000", tp(4, "33.3333% 99999px, 2.5cm -5%", 8));
    TEST_ASSERT_EQUAL_STRING("0 ", ttx(12));
    TEST_ASSERT_EQUAL_STRING("1: -/0/1 5000/1 999990000", tp(4, "0.5px 99999px", 1));
    TEST_ASSERT_EQUAL_STRING("13 0.5px 99999px", ttx(64));
    TEST_ASSERT_EQUAL_STRING("-1", tp(4, "5 -3.4629%", 3));
    TEST_ASSERT_EQUAL_STRING("-1", tp(4, "auto,auto 100000px,1em", 2));
    TEST_ASSERT_EQUAL_STRING("1: -/0/1 160000/1 -2555800", tp(4, "12pt -255.58px", 8));
    TEST_ASSERT_EQUAL_STRING("14 16px -255.58px", ttx(64));
    TEST_ASSERT_EQUAL_STRING("-1", tp(4, "99999px -37%, 33.3333%, auto 3mm,", 4));
    TEST_ASSERT_EQUAL_STRING("3: -/0/2 125000/2 1317000 -/0/2 0/0 0 -/0/1 -799000/2 40170", tp(4, "12.5% 131.7%, 0% auto, -79.9px 4.017%", 4));
    TEST_ASSERT_EQUAL_STRING("37 12.5% 131.7%, 0% auto, -79.9px 4.017%", ttx(128));
    TEST_ASSERT_EQUAL_STRING("3: -/0/1 123457/1 123457 -/0/2 125000/1 0 -/0/0 0/0 0", tp(4, "12.34567px,12.5% 0px,auto", 4));
    TEST_ASSERT_EQUAL_STRING("0 ", ttx(8));
    TEST_ASSERT_EQUAL_STRING("2: -/0/1 -1202000/2 100000 -/0/1 944882/1 944882", tp(4, "-120.2px 10%,2.5cm", 2));
    TEST_ASSERT_EQUAL_STRING("0 ", ttx(12));
    TEST_ASSERT_EQUAL_STRING("-1", tp(4, "1pc,auto,auto,108.2%", 1));
    TEST_ASSERT_EQUAL_STRING("-1", tp(4, "5, 150% auto, 98.045% -5%", 3));
    TEST_ASSERT_EQUAL_STRING("-1", tp(4, "-5%, auto, 1in, 0px, 33.3333%", 8));
}

